/// The axis of each of the nr rotors (columns of a 3 x 8): its nominal axis, turned about its
/// gimbal (rot_gi = gimbal index + 1, 0 fixed) by the gimbal angle.
/// - nr: int (passed a whole number)
/// - rot_a0: real[1][3][8] (passed a plain number)
/// - rot_gi: int[8] (passed a whole number)
/// - gim_axis: real[1][3][4] (passed a plain number)
/// - delta: real[1][4] (passed a plain number)
/// - returns a: real[1][8][3] (passed a plain number)
#[allow(clippy::too_many_arguments)]
pub fn rotor_axes(nr: i64, rot_a0: [[f64; 3]; 8], rot_gi: [i64; 8], gim_axis: [[f64; 3]; 4], delta: [f64; 4]) -> [[f64; 8]; 3] {
    let mut a: [[f64; 8]; 3] = [[0.0; 8]; 3];
    a = [[0.0; 8]; 3];
    {
        let __end1: i64 = nr;
        let mut i: i64 = 0;
        while i < __end1 {
            let mut a0: [f64; 3] = rot_a0[(i) as usize];
            if (rot_gi[(i) as usize] > 0) {
                let mut j: i64 = (rot_gi[(i) as usize] - 1);
                let mut t0: [f64; 3] = rt::cross(gim_axis[(j) as usize], a0);
                {
                    let __end2: i64 = 3;
                    let mut k: i64 = 0;
                    while k < __end2 {
                        a[(k) as usize][(i) as usize] = ((f64::cos(delta[(j) as usize]) * a0[(k) as usize]) + (f64::sin(delta[(j) as usize]) * t0[(k) as usize]));
                        k += 1;
                    }
                }
            } else {
                {
                    let __end3: i64 = 3;
                    let mut k: i64 = 0;
                    while k < __end3 {
                        a[(k) as usize][(i) as usize] = a0[(k) as usize];
                        k += 1;
                    }
                }
            }
            i += 1;
        }
    }
    a
}

/// The determinant by the first row.
/// - m: real[1][3][3] (passed a plain number)
/// - returns d: real[1] (passed a plain number)
#[allow(clippy::too_many_arguments)]
pub fn det3(m: [[f64; 3]; 3]) -> f64 {
    let mut d: f64 = 0.0;
    d = (((m[0][0] * ((m[1][1] * m[2][2]) - (m[1][2] * m[2][1]))) - (m[0][1] * ((m[1][0] * m[2][2]) - (m[1][2] * m[2][0])))) + (m[0][2] * ((m[1][0] * m[2][1]) - (m[1][1] * m[2][0]))));
    d
}

/// The inverse by the adjugate; a singular matrix (|det| < 1e-300) gives zeros and ok = false.
/// - m: real[1][3][3] (passed a plain number)
/// - returns r: real[1][3][3] (passed a plain number)
/// - returns ok: bool (passed true or false)
#[allow(clippy::too_many_arguments)]
pub fn inv3(m: [[f64; 3]; 3]) -> ([[f64; 3]; 3], bool) {
    let mut r: [[f64; 3]; 3] = [[0.0; 3]; 3];
    let mut ok: bool = false;
    let mut d: f64 = crate::gen::act::det3(m);
    ok = (rt::fabs(d) >= 1.0e-300);
    if ok {
        r[0] = [(((m[1][1] * m[2][2]) - (m[1][2] * m[2][1])) / d), (((m[0][2] * m[2][1]) - (m[0][1] * m[2][2])) / d), (((m[0][1] * m[1][2]) - (m[0][2] * m[1][1])) / d)];
        r[1] = [(((m[1][2] * m[2][0]) - (m[1][0] * m[2][2])) / d), (((m[0][0] * m[2][2]) - (m[0][2] * m[2][0])) / d), (((m[0][2] * m[1][0]) - (m[0][0] * m[1][2])) / d)];
        r[2] = [(((m[1][0] * m[2][1]) - (m[1][1] * m[2][0])) / d), (((m[0][1] * m[2][0]) - (m[0][0] * m[2][1])) / d), (((m[0][0] * m[1][1]) - (m[0][1] * m[1][0])) / d)];
    }
    (r, ok)
}

